     1→import { useState } from 'react';
     2→import { Pressable, StyleSheet, Text, View } from 'react-native';
     3→import type { ChecklistItem } from '../lib/data';
     4→import { riskLevel } from '../lib/risk';
     5→
     6→type Question = Extract<ChecklistItem, { kind: 'question' }>;
     7→
     8→type Props = {
     9→  item: Question;
    10→  onAnswer: (id: string, value: 'yes' | 'no') => void;
    11→};
    12→
    13→export function QuestionRow({ item, onAnswer }: Props) {
    14→  // Local copy so the pill highlights instantly, before the list re-renders.
    15→  const [answer, setAnswer] = useState(item.answer);
    16→  const risk = riskLevel(item.title);
    17→
    18→  return (
    19→    <View style={styles.row}>
    20→      {risk === 'high' && <Text style={styles.risk}>!</Text>}
    21→      <Text style={styles.question}>{item.title}</Text>
    22→      {(['yes', 'no'] as const).map(v => (
    23→        <Pressable
    24→          key={v}
    25→          accessibilityRole="button"
    26→          accessibilityLabel={`${v} for ${item.title}`}
    27→          accessibilityState={{ selected: answer === v }}
    28→          onPress={() => {
    29→            setAnswer(v);
    30→            onAnswer(item.id, v);
    31→          }}
    32→          style={[styles.pill, answer === v && styles.pillOn]}
    33→        >
    34→          <Text>{v}</Text>
    35→        </Pressable>
    36→      ))}
    37→    </View>
    38→  );
    39→}
    40→
    41→const styles = StyleSheet.create({
    42→  row: { flexDirection: 'row', alignItems: 'center', gap: 8, padding: 16 },
